// Package shellp implements the "shell" output format: a document tree is
// flattened into shell variable assignments, one per line, e.g.
//
//	a_b=1
//	a_c_0=x
//	d='str val'
//
// The format is output-only; decoding shell variables is not supported by
// the original tool either.
package shellp

import (
	"errors"
	"io"
	"strconv"
	"strings"

	"yq/node"
	"yq/settings"
)

// Decode always fails: the original tool reports
// "Error: no support for shell input format" for -p shell.
func Decode(data []byte, s *settings.Settings) ([]*node.Node, error) {
	return nil, errors.New("no support for shell input format")
}

// Encode flattens every result node into shell variable assignments.
//
// Probed behavior of the original binary:
//   - maps recurse, joining path segments with s.ShellKeySeparator;
//   - sequence elements use their index as the next segment (a root-level
//     sequence therefore yields _0=..., _1=..., ...);
//   - a scalar root uses the literal variable name "value";
//   - empty maps/sequences emit nothing at all;
//   - multiple results/documents are simply concatenated (no "---" lines);
//   - each assignment ends with "\n", or "\x00" with s.NulOutput;
//   - colors and UnwrapScalar have no effect.
func Encode(w io.Writer, nodes []*node.Node, s *settings.Settings) error {
	lineEnd := "\n"
	if s.NulOutput {
		lineEnd = "\x00"
	}
	var b strings.Builder
	for _, n := range nodes {
		emitNode(&b, "", n, s)
	}
	out := b.String()
	if lineEnd != "\n" {
		out = strings.ReplaceAll(out, "\n", lineEnd)
	}
	_, err := io.WriteString(w, out)
	return err
}

// emitNode appends the assignments for n to b. path is the variable name
// accumulated so far ("" at the document root).
func emitNode(b *strings.Builder, path string, n *node.Node, s *settings.Settings) {
	if n == nil {
		return
	}
	if n.Kind == node.AliasKind && n.Alias != nil {
		n = n.Alias
	}
	switch n.Kind {
	case node.DocumentKind:
		if root := n.Root(); root != nil {
			emitNode(b, path, root, s)
		}
	case node.MappingKind:
		for i := 0; i+1 < len(n.Content); i += 2 {
			name := sanitizeKey(n.Content[i].Value)
			if path != "" {
				name = path + s.ShellKeySeparator + name
			}
			emitNode(b, name, n.Content[i+1], s)
		}
	case node.SequenceKind:
		for i, el := range n.Content {
			emitNode(b, path+s.ShellKeySeparator+strconv.Itoa(i), el, s)
		}
	default: // scalars (and anything unexpected) print as name=value
		name := path
		if name == "" {
			name = "value"
		}
		if len(name) > 0 && name[0] >= '0' && name[0] <= '9' {
			name = "_" + name
		}
		b.WriteString(name)
		b.WriteByte('=')
		b.WriteString(quoteValue(n.Value))
		b.WriteByte('\n')
	}
}

// quoteValue renders a scalar value: bare when it consists solely of shell
// word characters [a-zA-Z0-9_] (or is empty), otherwise single-quoted with
// the classic '"'"' escape for embedded single quotes. Everything else,
// including double quotes and newlines, is left literal inside the quotes.
func quoteValue(v string) string {
	bare := true
	for i := 0; i < len(v); i++ {
		if !isWordByte(v[i]) {
			bare = false
			break
		}
	}
	if bare {
		return v
	}
	return "'" + strings.ReplaceAll(v, "'", `'"'"'`) + "'"
}

// sanitizeKey converts a map key into a shell-name-safe segment: the key is
// NFKD-decomposed (so "é" becomes "e", "ﬁ" becomes "fi"), ASCII word
// characters are kept, other ASCII characters become '_', and remaining
// non-ASCII characters are dropped. An empty result becomes "_".
// Note: this replacement character is always '_', independent of
// s.ShellKeySeparator (which only joins path segments) — probed behavior.
func sanitizeKey(key string) string {
	var b strings.Builder
	writeByte := func(c byte) {
		if isWordByte(c) {
			b.WriteByte(c)
		} else {
			b.WriteByte('_')
		}
	}
	for _, r := range key {
		if r < 128 {
			writeByte(byte(r))
		} else if dec, ok := nfkdASCII[r]; ok {
			for i := 0; i < len(dec); i++ {
				if dec[i] < 128 {
					writeByte(dec[i])
				}
				// non-ASCII remainder of a decomposition (e.g. combining
				// marks) is dropped
			}
		}
		// non-ASCII runes without an ASCII-bearing decomposition are dropped
	}
	if b.Len() == 0 {
		return "_"
	}
	return b.String()
}

func isWordByte(c byte) bool {
	return c == '_' ||
		(c >= '0' && c <= '9') ||
		(c >= 'a' && c <= 'z') ||
		(c >= 'A' && c <= 'Z')
}

