package shellp

import (
	"bytes"
	"testing"

	"yq/node"
	"yq/settings"
)

// Every expected output in this file was captured by running the original
// binary (/workspace/executable, yq v4.52.5) with the equivalent YAML input.

func mapNode(pairs ...*node.Node) *node.Node {
	m := node.NewMapping()
	m.Content = pairs
	return m
}

func kv(key string, val *node.Node) []*node.Node {
	return []*node.Node{node.NewString(key), val}
}

func encode(t *testing.T, s *settings.Settings, nodes ...*node.Node) string {
	t.Helper()
	var buf bytes.Buffer
	if err := Encode(&buf, nodes, s); err != nil {
		t.Fatalf("Encode returned error: %v", err)
	}
	return buf.String()
}

// printf 'a:\n  b: 1\n  c: [x, y]\nd: "str val"\n' | yq -o shell
func TestBasicNested(t *testing.T) {
	root := mapNode(
		node.NewString("a"), mapNode(
			node.NewString("b"), node.NewScalar("!!int", "1"),
			node.NewString("c"), &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
				node.NewString("x"), node.NewString("y"),
			}},
		),
		node.NewString("d"), node.NewString("str val"),
	)
	got := encode(t, settings.New(), root)
	want := "a_b=1\na_c_0=x\na_c_1=y\nd='str val'\n"
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

// Scalar rendering: null/bool/int-ish values print verbatim; quoting depends
// only on the character set of the value string, not on the YAML tag.
//
//	printf 'n: null\nb1: true\nf: 1.5\ni: -3\ne: 1e3\ns5: ""\n...' | yq -o shell
func TestScalarRendering(t *testing.T) {
	root := mapNode(
		node.NewString("n"), node.NewNull(),
		node.NewString("b1"), node.NewScalar("!!bool", "true"),
		node.NewString("b2"), node.NewScalar("!!bool", "false"),
		node.NewString("f"), node.NewScalar("!!float", "1.5"),
		node.NewString("i"), node.NewScalar("!!int", "-3"),
		node.NewString("e"), node.NewScalar("!!float", "1e3"),
		node.NewString("f1"), node.NewScalar("!!float", "1.50"),
		node.NewString("i1"), node.NewScalar("!!int", "0x1F"),
		node.NewString("s1"), node.NewString("hello"),
		node.NewString("s5"), node.NewString(""),
		node.NewString("s6"), node.NewString("new\nline"),
		node.NewString("s7"), node.NewString("yes"),
		node.NewString("t"), node.NewScalar("!!timestamp", "2020-01-01"),
		node.NewString("q"), node.NewString("it's"),
		node.NewString("dq"), node.NewString(`with"quote`),
		node.NewString("k"), node.NewString("123"),
	)
	got := encode(t, settings.New(), root)
	want := "n=null\n" +
		"b1=true\n" +
		"b2=false\n" +
		"f='1.5'\n" +
		"i='-3'\n" +
		"e=1e3\n" +
		"f1='1.50'\n" +
		"i1=0x1F\n" +
		"s1=hello\n" +
		"s5=\n" +
		"s6='new\nline'\n" +
		"s7=yes\n" +
		"t='2020-01-01'\n" +
		"q='it'\"'\"'s'\n" +
		"dq='with\"quote'\n" +
		"k=123\n"
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

// The unquoted-value character set is exactly [a-zA-Z0-9_].
// Probed one key at a time, e.g. printf 'k: "a.b"\n' | yq -o shell -> k='a.b'
func TestQuotingCharset(t *testing.T) {
	cases := []struct{ in, want string }{
		{"a.b", "'a.b'"}, {"a/b", "'a/b'"}, {"a~b", "'a~b'"}, {"a@b", "'a@b'"},
		{"a+b", "'a+b'"}, {"a%b", "'a%b'"}, {"a=b", "'a=b'"}, {"a:b", "'a:b'"},
		{"a,b", "'a,b'"}, {"a-b", "'a-b'"}, {"a b", "'a b'"}, {"a#b", "'a#b'"},
		{"a*b", "'a*b'"}, {"a!b", "'a!b'"}, {"a$b", "'a$b'"}, {"~", "'~'"},
		{"a_b", "a_b"}, {"ABC", "ABC"}, {"a0", "a0"}, {"0a", "0a"},
		{"nullx", "nullx"}, {"true1", "true1"}, {"héllo", "'héllo'"},
	}
	for _, c := range cases {
		root := mapNode(kv("k", node.NewString(c.in))...)
		got := encode(t, settings.New(), root)
		want := "k=" + c.want + "\n"
		if got != want {
			t.Errorf("value %q: got %q, want %q", c.in, got, want)
		}
	}
}

// Root scalar -> value=..., root sequence -> _0=..., root null -> value=null.
//
//	printf 'scalar root' | yq -o shell        -> value='scalar root'
//	printf -- '- a\n- b\n' | yq -o shell      -> _0=a / _1=b
//	printf 'null' | yq -o shell               -> value=null
func TestRoots(t *testing.T) {
	s := settings.New()
	if got := encode(t, s, node.NewString("scalar root")); got != "value='scalar root'\n" {
		t.Errorf("scalar root: got %q", got)
	}
	if got := encode(t, s, node.NewScalar("!!int", "123")); got != "value=123\n" {
		t.Errorf("int root: got %q", got)
	}
	if got := encode(t, s, node.NewNull()); got != "value=null\n" {
		t.Errorf("null root: got %q", got)
	}
	seq := &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
		node.NewString("a"), node.NewString("b"),
	}}
	if got := encode(t, s, seq); got != "_0=a\n_1=b\n" {
		t.Errorf("seq root: got %q", got)
	}
	// sequence of maps at root: printf -- '- a: 1\n- 2\n' | yq -o shell
	seq2 := &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
		mapNode(kv("a", node.NewScalar("!!int", "1"))...),
		node.NewScalar("!!int", "2"),
	}}
	if got := encode(t, s, seq2); got != "_0_a=1\n_1=2\n" {
		t.Errorf("seq-of-map root: got %q", got)
	}
}

// Deep nesting incl. maps inside sequences inside maps.
//
//	printf 'k:\n  - a: 1\n    b: [2, 3]\n  - c\nd:\n  e:\n    f: deep\n' | yq -o shell
func TestDeepNesting(t *testing.T) {
	root := mapNode(
		node.NewString("k"), &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
			mapNode(
				node.NewString("a"), node.NewScalar("!!int", "1"),
				node.NewString("b"), &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
					node.NewScalar("!!int", "2"), node.NewScalar("!!int", "3"),
				}},
			),
			node.NewString("c"),
		}},
		node.NewString("d"), mapNode(
			node.NewString("e"), mapNode(kv("f", node.NewString("deep"))...),
		),
	)
	got := encode(t, settings.New(), root)
	want := "k_0_a=1\nk_0_b_0=2\nk_0_b_1=3\nk_1=c\nd_e_f=deep\n"
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

// Key sanitization: NFKD decomposition, ASCII word chars kept, other ASCII
// -> '_', other non-ASCII dropped, empty -> "_", leading digit -> "_" prefix.
// All expectations probed from the original binary.
func TestKeySanitization(t *testing.T) {
	cases := []struct{ key, want string }{
		{"weird key", "weird_key"},
		{"key with space", "key_with_space"},
		{"UPPER", "UPPER"},
		{"MixEd", "MixEd"},
		{"with-hyphen", "with_hyphen"},
		{"under_score", "under_score"},
		{"9digit", "_9digit"},
		{"9", "_9"},
		{"a.b", "a_b"}, {"a/b", "a_b"}, {"a-b", "a_b"}, {"a@b", "a_b"},
		{"a+b", "a_b"}, {"a%b", "a_b"}, {"a!b", "a_b"}, {"a?b", "a_b"},
		{"a  b", "a__b"}, // each invalid char replaced individually
		{" a", "_a"}, {"a ", "a_"},
		{"", "_"}, {"!", "_"}, {"#", "_"},
		{"a_b", "a_b"},
		// non-ASCII: NFKD decomposition keeps ASCII base letters
		{"é", "e"}, {"é", "e"}, {"café", "cafe"}, {"Zürich", "Zurich"},
		{"ñ", "n"}, {"ü", "u"}, {"Å", "A"}, {"ç", "c"}, {"Å", "A"},
		{"ké y", "ke_y"}, {"aéb", "aeb"}, {"a é b", "a_e_b"},
		{"Ā", "A"}, {"Ṿ", "V"}, {"Ǆ", "DZ"},
		{"ﬁ", "fi"}, {"ﬀ", "ff"},
		{"²", "_2"}, {"①", "_1"}, {"①x", "_1x"}, {"⑵", "_2_"},
		{"Ａ", "A"},
		{"½", "_12"}, // NFKD: 1 + U+2044 (dropped) + 2
		// no decomposition -> dropped
		{"ß", "_"}, {"日", "_"}, {"œ", "_"}, {"ø", "_"}, {"Æ", "_"},
		{"ı", "_"}, {"đ", "_"}, {"ŋ", "_"}, {"α", "_"}, {"д", "_"},
	}
	for _, c := range cases {
		root := mapNode(kv(c.key, node.NewScalar("!!int", "1"))...)
		got := encode(t, settings.New(), root)
		want := c.want + "=1\n"
		if got != want {
			t.Errorf("key %q: got %q, want %q", c.key, got, want)
		}
	}
}

// --shell-key-separator only joins path segments; character replacement
// inside keys stays '_' and the leading-digit prefix stays '_' (probed with
// --shell-key-separator '.' and '').
func TestKeySeparatorSetting(t *testing.T) {
	s := settings.New()
	s.ShellKeySeparator = "."
	root := mapNode(
		node.NewString("a"), mapNode(kv("9x", node.NewScalar("!!int", "1"))...),
		node.NewString("b_c"), mapNode(kv("d-e", node.NewScalar("!!int", "2"))...),
		node.NewString("!"), node.NewScalar("!!int", "3"),
		node.NewString("a b"), node.NewScalar("!!int", "4"),
		node.NewString("日"), node.NewScalar("!!int", "5"),
		node.NewString("9x"), node.NewScalar("!!int", "6"),
	)
	got := encode(t, s, root)
	want := "a.9x=1\nb_c.d_e=2\n_=3\na_b=4\n_=5\n_9x=6\n"
	if got != want {
		t.Errorf("separator '.': got %q, want %q", got, want)
	}

	s2 := settings.New()
	s2.ShellKeySeparator = ""
	root2 := mapNode(
		node.NewString("a"), mapNode(kv("b", node.NewScalar("!!int", "1"))...),
		node.NewString("x y"), node.NewScalar("!!int", "2"),
	)
	if got := encode(t, s2, root2); got != "ab=1\nx_y=2\n" {
		t.Errorf("separator '': got %q", got)
	}

	s3 := settings.New()
	s3.ShellKeySeparator = "--"
	root3 := mapNode(kv("a", mapNode(kv("b", node.NewScalar("!!int", "1"))...))...)
	if got := encode(t, s3, root3); got != "a--b=1\n" {
		t.Errorf("separator '--': got %q", got)
	}
}

// Joining always inserts the separator even when the parent segment already
// ends with one: printf '"a ": {b: 1}\n' | yq -o shell -> a__b=1
func TestJoinAfterTrailingUnderscore(t *testing.T) {
	root := mapNode(kv("a ", mapNode(kv("b", node.NewScalar("!!int", "1"))...))...)
	if got := encode(t, settings.New(), root); got != "a__b=1\n" {
		t.Errorf("got %q", got)
	}
}

// Empty maps and sequences emit nothing at all:
//
//	printf 'a: {}\nb: 1\nc: []\nd: [[], {}]\n' | yq -o shell -> b=1
func TestEmptyCollections(t *testing.T) {
	root := mapNode(
		node.NewString("a"), node.NewMapping(),
		node.NewString("b"), node.NewScalar("!!int", "1"),
		node.NewString("c"), node.NewSequence(),
		node.NewString("d"), &node.Node{Kind: node.SequenceKind, Tag: "!!seq", Content: []*node.Node{
			node.NewSequence(), node.NewMapping(),
		}},
	)
	if got := encode(t, settings.New(), root); got != "b=1\n" {
		t.Errorf("got %q", got)
	}
	if got := encode(t, settings.New(), node.NewMapping()); got != "" {
		t.Errorf("root empty map: got %q", got)
	}
}

// Multiple results/documents are concatenated with no separators:
//
//	printf 'a: 1\n---\nb: 2\n' | yq -o shell -> a=1 / b=2
func TestMultipleResults(t *testing.T) {
	got := encode(t, settings.New(),
		mapNode(kv("a", node.NewScalar("!!int", "1"))...),
		mapNode(kv("b", node.NewScalar("!!int", "2"))...),
	)
	if got != "a=1\nb=2\n" {
		t.Errorf("got %q", got)
	}
}

// -0/--nul-output terminates assignments with NUL instead of newline;
// newlines inside values are preserved:
//
//	printf 'a: 1\n---\nb: 2\n' | yq -0 -o shell -> a=1\0b=2\0
func TestNulOutput(t *testing.T) {
	s := settings.New()
	s.NulOutput = true
	got := encode(t, s,
		mapNode(kv("a", node.NewScalar("!!int", "1"))...),
		mapNode(kv("b", node.NewScalar("!!int", "2"))...),
	)
	if got != "a=1\x00b=2\x00" {
		t.Errorf("got %q", got)
	}
	got = encode(t, s, mapNode(kv("k", node.NewString("new\nline"))...))
	if got != "k='new\nline'\x00" {
		t.Errorf("nul with newline value: got %q", got)
	}
}

// Aliases are followed to their target:
//
//	printf 'a: &x 1\nb: *x\n' | yq -o shell -> a=1 / b=1
func TestAlias(t *testing.T) {
	anchor := node.NewScalar("!!int", "1")
	alias := &node.Node{Kind: node.AliasKind, Value: "x", Alias: anchor}
	root := mapNode(
		node.NewString("a"), anchor,
		node.NewString("b"), alias,
	)
	if got := encode(t, settings.New(), root); got != "a=1\nb=1\n" {
		t.Errorf("got %q", got)
	}
}

// Colors and unwrapScalar have no effect on shell output (probed -C and
// --unwrapScalar=false).
func TestFlagsHaveNoEffect(t *testing.T) {
	s := settings.New()
	s.Colors = true
	s.UnwrapScalar = false
	s.Indent = 8
	root := mapNode(kv("a", node.NewScalar("!!int", "1"))...)
	if got := encode(t, s, root); got != "a=1\n" {
		t.Errorf("got %q", got)
	}
}

// printf ... | yq -p shell -> "Error: no support for shell input format", exit 1
func TestDecodeNotSupported(t *testing.T) {
	_, err := Decode([]byte("a_b=1\n"), settings.New())
	if err == nil {
		t.Fatal("expected error")
	}
	if err.Error() != "no support for shell input format" {
		t.Errorf("got %q", err.Error())
	}
}
